-- Generated by scripts/build-sprint3.py. Run before starting NocoBase.
BEGIN;

CREATE TABLE IF NOT EXISTS "attendanceEvents" (
 id bigint PRIMARY KEY, name varchar(255) NOT NULL, "venueId" bigint NOT NULL REFERENCES venues(id),
 "startsAt" timestamptz, status varchar(255) NOT NULL DEFAULT 'active' CHECK (status IN ('active','closed')),
 "totalEntries" bigint NOT NULL DEFAULT 0 CHECK ("totalEntries" >= 0),
 "totalExits" bigint NOT NULL DEFAULT 0 CHECK ("totalExits" >= 0),
 "currentInside" bigint NOT NULL DEFAULT 0 CHECK ("currentInside" >= 0),
 "createdAt" timestamptz, "updatedAt" timestamptz, "createdById" bigint, "updatedById" bigint,
 CHECK ("currentInside" = "totalEntries" - "totalExits")
);

CREATE TABLE IF NOT EXISTS "entryRecords" (
      id bigint PRIMARY KEY, "eventId" bigint NOT NULL REFERENCES "attendanceEvents"(id),
      "entranceId" bigint NOT NULL REFERENCES entrances(id), "requestKey" varchar(128) NOT NULL UNIQUE,
      "createdAt" timestamptz, "updatedAt" timestamptz, "createdById" bigint, "updatedById" bigint
    );
    CREATE INDEX IF NOT EXISTS "entryRecords_event_time" ON "entryRecords" ("eventId", "createdAt" DESC);
CREATE TABLE IF NOT EXISTS "exitRecords" (
      id bigint PRIMARY KEY, "eventId" bigint NOT NULL REFERENCES "attendanceEvents"(id),
      "entranceId" bigint NOT NULL REFERENCES entrances(id), "requestKey" varchar(128) NOT NULL UNIQUE,
      "createdAt" timestamptz, "updatedAt" timestamptz, "createdById" bigint, "updatedById" bigint
    );
    CREATE INDEX IF NOT EXISTS "exitRecords_event_time" ON "exitRecords" ("eventId", "createdAt" DESC);

CREATE OR REPLACE FUNCTION clicker_record_attendance() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE ev "attendanceEvents"%ROWTYPE; place venues%ROWTYPE; station entrances%ROWTYPE; delta integer;
BEGIN
  delta := CASE WHEN TG_TABLE_NAME = 'entryRecords' THEN 1 ELSE -1 END;
  IF NEW."requestKey" IS NULL OR length(NEW."requestKey") < 8 THEN
    RAISE EXCEPTION 'A request ID of at least 8 characters is required';
  END IF;
  SELECT * INTO ev FROM "attendanceEvents" WHERE id = NEW."eventId" FOR UPDATE;
  IF NOT FOUND OR ev.status <> 'active' THEN RAISE EXCEPTION 'Select an active event'; END IF;
  SELECT * INTO place FROM venues WHERE id = ev."venueId" FOR UPDATE;
  SELECT * INTO station FROM entrances WHERE id = NEW."entranceId" FOR SHARE;
  IF NOT FOUND OR NOT station.active OR station."venueId" <> ev."venueId"
    OR station."directionType" NOT IN ('both', CASE WHEN delta = 1 THEN 'in' ELSE 'out' END) THEN
    RAISE EXCEPTION 'Select an active station for this event and direction';
  END IF;
  IF delta = 1 AND place.status <> 'open' THEN RAISE EXCEPTION 'Venue is closed for entry'; END IF;
  IF delta = 1 AND (place."maxCapacity" IS NULL OR place."currentCount" >= place."maxCapacity") THEN
    RAISE EXCEPTION 'Venue is at capacity';
  END IF;
  IF delta = -1 AND (ev."currentInside" <= 0 OR place."currentCount" <= 0) THEN
    RAISE EXCEPTION 'Attendance is zero; an exit cannot be recorded';
  END IF;
  UPDATE "attendanceEvents" SET "currentInside" = "currentInside" + delta,
    "totalEntries" = "totalEntries" + CASE WHEN delta = 1 THEN 1 ELSE 0 END,
    "totalExits" = "totalExits" + CASE WHEN delta = -1 THEN 1 ELSE 0 END,
    "updatedAt" = now(), "updatedById" = NEW."createdById" WHERE id = ev.id;
  UPDATE venues SET "currentCount" = "currentCount" + delta, "updatedAt" = now(),
    "updatedById" = NEW."createdById" WHERE id = place.id;
  NEW."createdAt" := now(); NEW."updatedAt" := now();
  RETURN NEW;
END; $$;
CREATE OR REPLACE FUNCTION clicker_immutable_record() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN RAISE EXCEPTION 'Attendance records are append-only'; END; $$;

DROP TRIGGER IF EXISTS clicker_record ON "entryRecords";
    CREATE TRIGGER clicker_record BEFORE INSERT ON "entryRecords" FOR EACH ROW EXECUTE FUNCTION clicker_record_attendance();
    DROP TRIGGER IF EXISTS clicker_immutable ON "entryRecords";
    CREATE TRIGGER clicker_immutable BEFORE UPDATE OR DELETE ON "entryRecords" FOR EACH ROW EXECUTE FUNCTION clicker_immutable_record();
DROP TRIGGER IF EXISTS clicker_record ON "exitRecords";
    CREATE TRIGGER clicker_record BEFORE INSERT ON "exitRecords" FOR EACH ROW EXECUTE FUNCTION clicker_record_attendance();
    DROP TRIGGER IF EXISTS clicker_immutable ON "exitRecords";
    CREATE TRIGGER clicker_immutable BEFORE UPDATE OR DELETE ON "exitRecords" FOR EACH ROW EXECUTE FUNCTION clicker_immutable_record();
